    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch (platform-approved grant). RunInfo has no free-text
        // field, so its `date` is used as the query text. The result is
        // deliberately ignored: the node's output does not depend on it.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let urls = match crate::aap::caps::state_read::get("urls") {
            Some(text) => text
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
